// Generated from public/fonts (SIL OFL). Embedded so OG rendering needs no network, fs, or global-scope I/O on Workers.
export const ROBOTO_CONDENSED_900_B64 =
  ''

export const JETBRAINS_MONO_700_B64 =
  ''

export function decodeFont(b64: string): ArrayBuffer {
  const bin = atob(b64)
  const bytes = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i)
  return bytes.buffer
}
